import { useRef } from "react";
import { Banner, Button, ButtonGroup, Icon } from "@kit/index.js";
import { TrackingScope, Translate, useImpression, useTranslation, useUser } from "travel-platform";
import "./catalog.js";
import styles from "./MerchBanner.module.css";

export default function SignInBanner() {
    const t = useTranslation();
    const user = useUser();
    const ref = useRef(null);
    useImpression(ref, "banner:signin-top", { bannerId: "signin-top" });
    if (user.loggedIn)
        return null;
    return (
        <TrackingScope surface="banner-signin">
            <div ref={ref} className={styles.wrapper}>
                <Banner variant="accent" title={t("mb.signin_title")} image={<Icon name="sparkle" size="larger" className={styles.icon} />} action={<ButtonGroup><Button variant="primary" href="account/sign-in.html"><Translate id="mb.signin_cta" /></Button><Button variant="tertiary" href="account/register.html"><Translate id="mb.register_cta" /></Button></ButtonGroup>}>
                    <Translate id="mb.signin_body" />
                </Banner>
            </div>
        </TrackingScope>
    );
}
